  1→import { Badge } from "@/components/ui/badge";
  2→import { Button } from "@/components/ui/button";
  3→import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
  4→import { ScrollArea } from "@/components/ui/scroll-area";
  5→import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
  6→import { Phone, Mail, FileText, Archive, MapPin } from "lucide-react";
  7→import { toast } from "sonner";
  8→import type { Result } from "@/pages/Index";
  9→import type { HiringStage } from "@/hooks/useStageTracker";
 10→
 11→import CandidateSummary from "@/components/candidate/CandidateSummary";
 12→import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
 13→import ExperiencePanel from "@/components/candidate/ExperiencePanel";
 14→import EducationPanel from "@/components/candidate/EducationPanel";
 15→import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
 16→import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
 17→import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
 18→import StageTracker from "@/components/candidate/StageTracker";
 19→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
 20→import { useState } from "react";
 21→
 22→interface CandidateDetailSheetProps {
 23→  result: Result | null;
 24→  isOpen: boolean;
 25→  onClose: () => void;
 26→  jobId?: string | null;
 27→  jobTitle?: string | null;
 28→  formatCandidateName: (filename: string) => string;
 29→  onDownload: (filePath: string, filename: string) => void;
 30→  onDismiss: (resumeId: string) => void;
 31→  currentStage?: HiringStage | null;
 32→  stageUpdatedAt?: string | null;
 33→  onStageChange?: (resumeId: string, stage: HiringStage) => void;
 34→}
 35→
 36→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
 37→  if (score >= 70) return { label: "Strong", variant: "success" };
 38→  if (score >= 40) return { label: "Good", variant: "warning" };
 39→  return { label: "Weak", variant: "destructive" };
 40→};
 41→
 42→const getScoreColor = (score: number) => {
 43→  if (score >= 70) return "bg-score-skills";
 44→  if (score >= 40) return "bg-warning";
 45→  return "bg-destructive";
 46→};
 47→
 48→const CandidateDetailSheet = ({
 49→  result: r,
 50→  isOpen,
 51→  onClose,
 52→  jobId,
 53→  jobTitle,
 54→  formatCandidateName,
 55→  onDownload,
 56→  onDismiss,
 57→  currentStage,
 58→  stageUpdatedAt,
 59→  onStageChange,
 60→}: CandidateDetailSheetProps) => {
 61→  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
 62→
 63→  if (!r) return null;
 64→
 65→  const strength = getStrengthLabel(r.overall_score);
 66→  const candidateName = r.candidate_name || formatCandidateName(r.filename);
 67→
 68→  return (
 69→    <>
 70→      <Sheet open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
 71→        <SheetContent side="right" className="sm:max-w-2xl w-full p-0 flex flex-col">
 72→          {/* Header */}
 73→          <SheetHeader className="px-6 pt-6 pb-4 border-b border-border shrink-0">
 74→            <div className="flex items-start justify-between gap-4 pr-8">
 75→              <div className="space-y-1.5 min-w-0">
 76→                <SheetTitle className="text-lg font-semibold truncate">{candidateName}</SheetTitle>
 77→                <div className="flex items-center gap-2 flex-wrap">
 78→                  {r.candidate_location && (
 79→                    <span className="flex items-center gap-1 text-xs text-muted-foreground">
 80→                      <MapPin className="h-3 w-3" /> {r.candidate_location}
 81→                    </span>
 82→                  )}
 83→                  {r.candidate_email && (
 84→                    <span className="text-xs text-muted-foreground">{r.candidate_email}</span>
 85→                  )}
 86→                </div>
 87→              </div>
 88→            </div>
 89→
 90→            {/* Score + badges + actions */}
 91→            <div className="flex items-center gap-3 pt-2 flex-wrap">
 92→              <div className="flex items-center gap-2">
 93→                <div className="flex items-center gap-1.5">
 94→                  <div className="h-2 w-16 rounded-full bg-secondary overflow-hidden">
 95→                    <div className={`h-full rounded-full ${getScoreColor(r.overall_score)}`} style={{ width: `${Math.min(r.overall_score, 100)}%` }} />
 96→                  </div>
 97→                  <span className="text-sm font-semibold tabular-nums">{r.overall_score?.toFixed(0)}%</span>
 98→                </div>
 99→                <Badge variant={strength.variant}>{strength.label}</Badge>
100→              </div>
101→
102→              <div className="flex items-center gap-0.5 ml-auto">
103→                <TooltipProvider delayDuration={300}>
104→                  {r.candidate_phone && (
105→                    <Tooltip>
106→                      <TooltipTrigger asChild>
107→                        <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-primary"
108→                          onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
109→                          <Phone className="h-3.5 w-3.5" />
110→                        </Button>
111→                      </TooltipTrigger>
112→                      <TooltipContent>{r.candidate_phone}</TooltipContent>
113→                    </Tooltip>
114→                  )}
115→                  {r.candidate_email && (
116→                    <Tooltip>
117→                      <TooltipTrigger asChild>
118→                        <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-primary"
119→                          onClick={() => setEmailDialogOpen(true)}>
120→                          <Mail className="h-3.5 w-3.5" />
121→                        </Button>
122→                      </TooltipTrigger>
123→                      <TooltipContent>Email candidate</TooltipContent>
124→                    </Tooltip>
125→                  )}
126→                  {r.file_path && (
127→                    <Tooltip>
128→                      <TooltipTrigger asChild>
129→                        <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-primary"
130→                          onClick={() => onDownload(r.file_path!, r.filename)}>
131→                          <FileText className="h-3.5 w-3.5" />
132→                        </Button>
133→                      </TooltipTrigger>
134→                      <TooltipContent>Download resume</TooltipContent>
135→                    </Tooltip>
136→                  )}
137→                  <Tooltip>
138→                    <TooltipTrigger asChild>
139→                      <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-amber-500"
140→                        onClick={() => { onDismiss(r.resume_id); onClose(); }}>
141→                        <Archive className="h-3.5 w-3.5" />
142→                      </Button>
143→                    </TooltipTrigger>
144→                    <TooltipContent>Archive</TooltipContent>
145→                  </Tooltip>
146→                </TooltipProvider>
147→              </div>
148→            </div>
149→          </SheetHeader>
150→
151→          {/* Scrollable content */}
152→          <ScrollArea className="flex-1">
153→            <div className="px-6 py-5 space-y-5">
154→              {/* Summary */}
155→              <CandidateSummary result={r} />
156→
157→              {/* Stage Tracker */}
158→              {onStageChange && (
159→                <StageTracker
160→                  currentStage={currentStage || "applied"}
161→                  updatedAt={stageUpdatedAt}
162→                  onStageChange={(stage) => onStageChange(r.resume_id, stage)}
163→                />
164→              )}
165→
166→              {/* Strengths & Gaps */}
167→              <StrengthsGapsPanel result={r} />
168→
169→              {/* Skills | Experience | Education */}
170→              <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
171→                <SkillsDetailPanel result={r} />
172→                <ExperiencePanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves as string[]} />
173→                <EducationPanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves} missingMustHaves={r.missing_must_haves} />
174→              </div>
175→
176→              {/* JD Alignment */}
177→              <JDAlignedPanel result={r} />
178→
179→              {/* Interview Questions */}
180→              <InterviewQuestionsPanel result={r} />
181→            </div>
182→          </ScrollArea>
183→        </SheetContent>
184→      </Sheet>
185→
186→      {r.candidate_email && (
187→        <EmailOutreachDialog
188→          open={emailDialogOpen}
189→          onOpenChange={setEmailDialogOpen}
190→          candidateName={candidateName}
191→          candidateEmail={r.candidate_email}
192→          jobTitle={jobTitle || "Open Position"}
193→          matchScore={Math.round(r.overall_score ?? 0)}
194→          resumeId={r.resume_id}
195→          jobId={jobId || ""}
196→        />
197→      )}
198→    </>
199→  );
200→};
201→
202→export default CandidateDetailSheet;
203→
